import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static Scanner sc = new Scanner(System.in);
    static final int M = 998244353;
    static int n;
    static int[] hd = new int[5003],nx = new int[5003];
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		int t = sc.nextInt();
		StringBuilder sb = new StringBuilder();
		int[] d = new int[5003] , w = new int[5003];
		while(t-- >0){
		    n = sc.nextInt();
		    for(int i = 0 ; i<=n+1 ; i++){
		        hd[i] = 0;
		        d[i] = 0;
		        w[i] = 0;
		    }
		    for(int i = 1 ; i<=n ; i++){
		        int a = sc.nextInt();
		        nx[i] = hd[a];
		        hd[a] = i;
		    }
		    d[0] = 1;
		    for(int v = 1 ; v<n ; v++){
		        for(int l = 0 ; l<=v ; l++) w[l] = 0;
		        boolean em = hd[v] == 0;
		        for(int l = 0 ; l<v ; l++){
		            int c = d[l];
		            if(c == 0) continue;
		            int r = v-l-1;
		            if(em || ok(v,l+1,l,r)){
		                w[l+1]+=c;
		                if(w[l+1]>=M) w[l+1] -= M;
		            }
		            if(em || ok(v,n-r,l,r)){
		                w[l] +=c;
		                if(w[l]>=M) w[l] -=M;
		            }
		        }
		        int[] s = d;
		        d = w;
		        w = s;
 		    }
 		    long an = 0;
 		    for(int l = 0 ; l<n ; l++){
 		        if(d[l] == 0) continue;
 		        if(hd[n] == 0 || ok(n,l+1,l,n-l-1)) an+=d[l];
  		    }
  		    sb.append(an%M).append('\n');
		}
		System.out.print(sb);
		

	}
	static boolean ok(int v , int pos , int l , int r){
	    for(int i = hd[v] ; i!=0 ; i =  nx[i]){
	        boolean g = false;
	        if(i>=pos && 1+l + Math.max(0,i-n+r) == (i+1)/2) g = true;
	        else if(i<=pos && 1+Math.max(0 , l-i+1) + r == (n-i+2)/2) g = true;
	        if(!g) return false;
	    }
	    return true;
	}
}
